//! Generates a permission per command (`permissions/autogenerated/`) and builds the Kotlin library.

/// The commands Kotlin answers (`PlayerPlugin.kt`). The web UI reaches them through the app's
/// `window.LullNative` bridge; `registerListener`/`remove_listener` carry the events. `scan` is the
/// connect page's QR scanner, outside the default set the hub's web UI gets.
const COMMANDS: &[&str] = &[
    "load",
    "play",
    "pause",
    "seek",
    "set_volume",
    "set_next",
    "crossfade",
    "equalize",
    "download_add",
    "download_remove",
    "download_list",
    "download_usage",
    "scan",
    "registerListener",
    "remove_listener",
];

fn main() {
    tauri_plugin::Builder::new(COMMANDS).android_path("android").build();
}
